package cl.nexbyte.siger.institucional.notificaciones;
import cl.nexbyte.siger.institucional.nucleo.CatalogoLaboratorio.Operador;import cl.nexbyte.siger.institucional.nucleo.ContratosNucleo.Resultado;import cl.nexbyte.siger.institucional.robustez.*;
import java.time.*;import java.util.*;import java.security.*;import tools.jackson.databind.json.JsonMapper;
/** Tareas del propio funcionario. No se delegan ni producen actuaciones o cierres. */
public final class TareasPersonales {
 private final BaseJdbc db;private final RecursosNotificacion permisos;private final JsonMapper json;private final Clock clock;
 public TareasPersonales(BaseJdbc db,RecursosNotificacion permisos,JsonMapper json,Clock clock){this.db=db;this.permisos=permisos;this.json=json;this.clock=clock;}
 public record Edicion(long revision,String titulo,String descripcion,Instant recordatorio,Instant ventanaDesde,Instant ventanaHasta,Instant plazo,String prioridad,String tipoRecurso,UUID recurso,String responsable){@Override public String toString(){return "Edicion[datos privados]";}}
 public record Cambio(long revision,String estado,boolean confirmacionManual){}
 public record Tarea(UUID id,String titulo,String descripcion,String creador,String responsable,Instant creada,Instant recordatorio,Instant ventanaDesde,Instant ventanaHasta,Instant plazo,String prioridad,String estado,long revision,String tipoRecurso,UUID recurso,Instant completada,String completadaPor,boolean confirmacionManual){@Override public String toString(){return "Tarea[datos privados]";}}
 public record Historia(long secuencia,String autor,Instant fecha,long revision,String evento,Tarea datos){}
 private static Instant fecha(Map<String,Object> r,String k){return r.get(k)==null?null:Instant.ofEpochMilli(((Number)r.get(k)).longValue());}
 private static Long ms(Instant v){return v==null?null:v.toEpochMilli();}
 private Tarea vista(Map<String,Object> r){return new Tarea(UUID.fromString(r.get("id").toString()),r.get("title").toString(),r.get("description_text").toString(),r.get("creator_id").toString(),r.get("responsible_id").toString(),fecha(r,"created_ms"),fecha(r,"reminder_ms"),fecha(r,"execution_from_ms"),fecha(r,"execution_until_ms"),fecha(r,"deadline_ms"),r.get("priority_code").toString(),r.get("state").toString(),((Number)r.get("revision")).longValue(),(String)r.get("resource_type"),r.get("resource_id")==null?null:UUID.fromString(r.get("resource_id").toString()),fecha(r,"completed_ms"),(String)r.get("completed_by"),Boolean.TRUE.equals(r.get("manual_confirmed")));}
 private void validar(Operador a,Edicion e){if(e==null||e.titulo()==null||e.titulo().isBlank()||e.titulo().length()>180||e.descripcion()==null||e.descripcion().length()>6000||e.titulo().chars().anyMatch(Character::isISOControl)||!Set.of("BAJA","NORMAL","ALTA").contains(Objects.toString(e.prioridad(),"")))throw new FalloTecnico(400);
  if(e.responsable()!=null&&!a.id().equals(e.responsable()))throw new FalloTecnico(403,"TAREA_PERSONAL");
  if(e.ventanaHasta()!=null&&(e.ventanaDesde()==null||!e.ventanaHasta().isAfter(e.ventanaDesde())))throw new FalloTecnico(400);
  for(var date:Arrays.asList(e.recordatorio(),e.ventanaDesde(),e.ventanaHasta(),e.plazo()))if(date!=null&&(date.isBefore(Instant.parse("2000-01-01T00:00:00Z"))||date.isAfter(Instant.parse("2100-01-01T00:00:00Z"))))throw new FalloTecnico(400);
  if(!"CASO".equals(e.tipoRecurso())||e.recurso()==null)throw new FalloTecnico(400,"TAREA_REQUIERE_CASO");
  permisos.recurso(a,e.tipoRecurso(),e.recurso());
 }
 private void lock(Operador a){db.sql.queryForObject("SELECT id FROM identity_guard WHERE id=1 FOR UPDATE",Integer.class);permisos.actor(a);}
 private String hash(Object value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(value)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException();}}
 private Resultado anterior(Operador a,UUID key,String op,String digest){if(key==null)throw new FalloTecnico(400);var rows=db.sql.queryForList("SELECT * FROM task_command WHERE id=?",key.toString());if(rows.isEmpty())return null;var r=rows.getFirst();if(!a.id().equals(r.get("actor_id"))||!op.equals(r.get("action_code"))||!digest.equals(r.get("request_hash")))throw new FalloTecnico(409);var id=UUID.fromString(r.get("task_id").toString());leer(a,id);return new Resultado(id,((Number)r.get("result_revision")).longValue());}
 private Resultado comando(Operador a,UUID key,String op,String digest,UUID id,long revision){db.sql.update("INSERT INTO task_command VALUES(?,?,?,?,?,?)",key.toString(),a.id(),op,digest,id.toString(),revision);return new Resultado(id,revision);}
 private void historia(Operador a,UUID id,String code){var t=leer(a,id);db.sql.update("INSERT INTO task_history(task_id,actor_id,at_ms,revision,event_code,snapshot_doc) VALUES(?,?,?,?,?,?)",id.toString(),a.id(),clock.millis(),t.revision(),code,json.writeValueAsString(t));evento(id,t.revision(),code);}
 private void eventoTemporal(UUID id,long planned,String code){String key=id+":"+code+":"+planned;if(db.sql.queryForObject("SELECT COUNT(*) FROM workflow_event WHERE event_key=?",Integer.class,key)==0)db.sql.update("INSERT INTO workflow_event(event_key,code,resource_type,resource_id,at_ms) VALUES(?,? ,'TAREA',?,?)",key,code,id.toString(),clock.millis());}
 private void evento(UUID id,long revision,String code){String key=id+":"+revision+":"+code;if(db.sql.queryForObject("SELECT COUNT(*) FROM workflow_event WHERE event_key=?",Integer.class,key)==0)db.sql.update("INSERT INTO workflow_event(event_key,code,resource_type,resource_id,at_ms) VALUES(?,?,'TAREA',?,?)",key,code,id.toString(),clock.millis());}
 public Resultado crear(Operador a,UUID key,Edicion e){permisos.actor(a);validar(a,e);var digest=hash(e);return db.transaction(()->{lock(a);var prev=anterior(a,key,"CREAR",digest);if(prev!=null)return prev;validar(a,e);if(permisos.caso(a,e.recurso()).estado().equals("CERRADO"))throw new FalloTecnico(409,"CASO_CERRADO");var id=UUID.randomUUID();db.sql.update("INSERT INTO institution_task(id,creator_id,responsible_id,title,description_text,created_ms,reminder_ms,execution_from_ms,execution_until_ms,deadline_ms,priority_code,state,revision,resource_type,resource_id,manual_confirmed) VALUES(?,?,?,?,?,?,?,?,?,?,?,'PENDIENTE',0,?,?,FALSE)",id.toString(),a.id(),a.id(),e.titulo(),e.descripcion(),clock.millis(),ms(e.recordatorio()),ms(e.ventanaDesde()),ms(e.ventanaHasta()),ms(e.plazo()),e.prioridad(),e.tipoRecurso(),e.recurso()==null?null:e.recurso().toString());historia(a,id,"TAREA_CREADA");return comando(a,key,"CREAR",digest,id,0);});}
 public Tarea leer(Operador a,UUID id){if(id==null)throw new FalloTecnico(400);var r=permisos.fila("institution_task",id.toString());permisos.tarea(a,r);return vista(r);}
 public List<Tarea> listar(Operador a,String estado){permisos.actor(a);if(estado!=null&&!estado.isBlank()&&!Set.of("PENDIENTE","EN_CURSO","COMPLETADA","CANCELADA").contains(estado))throw new FalloTecnico(400);var rows=db.sql.queryForList("SELECT * FROM institution_task WHERE creator_id=? AND responsible_id=?"+(estado==null||estado.isBlank()?"":" AND state=?")+" ORDER BY created_ms DESC,id LIMIT 500",estado==null||estado.isBlank()?new Object[]{a.id(),a.id()}:new Object[]{a.id(),a.id(),estado});var items=new ArrayList<Tarea>();for(var r:rows)try{permisos.tarea(a,r);items.add(vista(r));}catch(FalloTecnico denied){if(!Set.of(401,403,404).contains(denied.status))throw denied;}return items;}
 public Resultado editar(Operador a,UUID key,UUID id,Edicion e){permisos.actor(a);validar(a,e);var digest=hash(List.of(id,e));return db.transaction(()->{lock(a);var prev=anterior(a,key,"EDITAR",digest);if(prev!=null)return prev;var t=leer(a,id);if(t.revision()!=e.revision())throw new FalloTecnico(409,"VERSION_OBSOLETA");if(Set.of("COMPLETADA","CANCELADA").contains(t.estado()))throw new FalloTecnico(409);validar(a,e);if(!t.recurso().equals(e.recurso())||permisos.caso(a,e.recurso()).estado().equals("CERRADO"))throw new FalloTecnico(409,"CONTEXTO_TAREA_NO_EDITABLE");db.sql.update("UPDATE institution_task SET title=?,description_text=?,reminder_ms=?,execution_from_ms=?,execution_until_ms=?,deadline_ms=?,priority_code=?,resource_type=?,resource_id=?,revision=revision+1 WHERE id=?",e.titulo(),e.descripcion(),ms(e.recordatorio()),ms(e.ventanaDesde()),ms(e.ventanaHasta()),ms(e.plazo()),e.prioridad(),e.tipoRecurso(),e.recurso()==null?null:e.recurso().toString(),id.toString());historia(a,id,"TAREA_MODIFICADA");return comando(a,key,"EDITAR",digest,id,t.revision()+1);});}
 public Resultado estado(Operador a,UUID key,UUID id,Cambio e){permisos.actor(a);if(e==null||!Set.of("PENDIENTE","EN_CURSO","COMPLETADA","CANCELADA").contains(Objects.toString(e.estado(),""))||e.estado().equals("COMPLETADA")!=e.confirmacionManual())throw new FalloTecnico(400);var digest=hash(List.of(id,e));return db.transaction(()->{lock(a);var prev=anterior(a,key,"ESTADO",digest);if(prev!=null)return prev;var t=leer(a,id);if(t.revision()!=e.revision())throw new FalloTecnico(409,"VERSION_OBSOLETA");if(Set.of("COMPLETADA","CANCELADA").contains(t.estado())||t.estado().equals(e.estado()))throw new FalloTecnico(409);if(Set.of("PENDIENTE","EN_CURSO").contains(e.estado())&&permisos.caso(a,t.recurso()).estado().equals("CERRADO"))throw new FalloTecnico(409,"CASO_CERRADO");boolean done=e.estado().equals("COMPLETADA");db.sql.update("UPDATE institution_task SET state=?,revision=revision+1,completed_ms=?,completed_by=?,manual_confirmed=? WHERE id=?",e.estado(),done?clock.millis():null,done?a.id():null,done,id.toString());historia(a,id,done?"TAREA_COMPLETADA":"TAREA_ESTADO_MODIFICADO");return comando(a,key,"ESTADO",digest,id,t.revision()+1);});}
 private Tarea datosHistoricos(Operador a,String doc){var t=json.readValue(doc,Tarea.class);try{permisos.recurso(a,t.tipoRecurso(),t.recurso());return t;}catch(FalloTecnico denied){if(Set.of(403,404).contains(denied.status))return null;throw denied;}}
 public List<Historia> historial(Operador a,UUID id){leer(a,id);return db.sql.queryForList("SELECT * FROM task_history WHERE task_id=? ORDER BY seq DESC LIMIT 100",id.toString()).stream().map(r->new Historia(((Number)r.get("seq")).longValue(),r.get("actor_id").toString(),fecha(r,"at_ms"),((Number)r.get("revision")).longValue(),r.get("event_code").toString(),datosHistoricos(a,r.get("snapshot_doc").toString()))).toList();}
 public void temporales(){db.transaction(()->{db.sql.queryForObject("SELECT id FROM notification_guard WHERE id=1 FOR UPDATE",Integer.class);var rows=db.sql.queryForList("SELECT id,revision,reminder_ms,deadline_ms FROM institution_task t WHERE state IN ('PENDIENTE','EN_CURSO') AND ((reminder_ms IS NOT NULL AND reminder_ms<=? AND NOT EXISTS(SELECT 1 FROM workflow_event e WHERE e.event_key=CONCAT(t.id,':TAREA_RECORDATORIO:',t.reminder_ms))) OR (deadline_ms IS NOT NULL AND deadline_ms<=? AND NOT EXISTS(SELECT 1 FROM workflow_event e WHERE e.event_key=CONCAT(t.id,':TAREA_VENCIDA:',t.deadline_ms)))) ORDER BY created_ms,id LIMIT 20",clock.millis(),clock.millis());for(var r:rows){var id=UUID.fromString(r.get("id").toString());long rev=((Number)r.get("revision")).longValue();if(r.get("reminder_ms")!=null&&((Number)r.get("reminder_ms")).longValue()<=clock.millis())eventoTemporal(id,((Number)r.get("reminder_ms")).longValue(),"TAREA_RECORDATORIO");if(r.get("deadline_ms")!=null&&((Number)r.get("deadline_ms")).longValue()<=clock.millis())eventoTemporal(id,((Number)r.get("deadline_ms")).longValue(),"TAREA_VENCIDA");}return null;});}
}
